import Root from "./1Adding Interactivity/2StateasSnapshot"
import { NotShared, Shared, UsingImmer } from "./1Adding Interactivity/5zCoreCocept"
import Sub from "./subReLearn"
import "./ReLearn.css"
import {useState} from "react"

export default function () {
  const [text, setText] = useState()
  return (
    <>
    <textarea value={text} onInput={e => {setText()}}></textarea>
    <p>{text}</p>
    </>
  );
}


// http://localhost:3000
